library(readr); library(dplyr); wave_one <- read_delim('data/input/wave_one_lsype_young_person_2020.tab', delim = '\t'); wave_two <- read_delim('data/input/wave_two_lsype_family_background_2020.tab', delim = '\t'); wave_three <- read_delim('data/input/wave_three_lsype_family_background_2020.tab', delim = '\t'); wave_four <- read_delim('data/input/wave_four_lsype_young_person_2020.tab', delim = '\t'); wave_nine <- read_delim('data/input/ns9_2022_derived_variables.tab', delim = '\t'); merged_data <- wave_one %>% full_join(wave_two, by = 'NSID') %>% full_join(wave_three, by = 'NSID') %>% full_join(wave_four, by = 'NSID') %>% full_join(wave_nine, by = 'NSID'); merged_data <- merged_data %>% mutate(IMDRSCORE_wave2 = ifelse(IMDRSCORE.x == -94, -8, IMDRSCORE.x), IMDRSCORE_wave3 = ifelse(IMDRSCORE.y == -94, -8, IMDRSCORE.y)); merged_data <- merged_data %>% mutate(imd15 = IMDRSCORE_wave2, imd16 = IMDRSCORE_wave3, imd32 = W9DIMDD); output_data <- merged_data %>% select(NSID, imd15, imd16, imd32); write_csv(output_data, 'data/output/cleaned_data.csv'); 'data/output/cleaned_data.csv'